            font-size: 18px;
            opacity: 0;
            transition: all 0.3s ease;
        }

        .choice-button:hover {
            transform: translateX(8px);
            box-shadow: 0 5px 20px rgba(255, 215, 0, 0.4);
            background: var(--pearl-white);
            border: 2px solid var(--primary-pink);
        }

        .choice-button:hover::before {
            opacity: 1;
            transform: translateY(-50%) scale(1.2);
        }

        /* 模态框样式 */
        #modal-overlay {
            position: fixed;
            top: 0; left: 0;
            width: 100%; height: 100%;
            background: rgba(0, 0, 0, 0.8);
            display: none;
            align-items: center;
            justify-content: center;
            z-index: 3000;
            backdrop-filter: blur(10px);
        }

        #modal-box {
            background: var(--pearl-white);
            padding: 25px;
            border-radius: 20px;
            min-width: 300px;
            max-width: 90%;
            box-shadow: 0 10px 40px rgba(255, 105, 180, 0.4);
            border: 3px solid var(--primary-pink);
            animation: modalAppear 0.4s ease;
            position: relative;
            overflow: hidden;
        }

        #modal-box::before {
            content: '';
            position: absolute;
            top: -2px; left: -2px; right: -2px; bottom: -2px;
            background: var(--gradient-pink);
            border-radius: 20px;
            z-index: -1;
        }

        @keyframes modalAppear {
            from {
                opacity: 0;
                transform: scale(0.8) translateY(-50px);
            }
            to {
                opacity: 1;
                transform: scale(1) translateY(0);
            }
        }

        #modal-title {
            margin: 0 0 15px 0;
            font-size: 1.4em;
            color: var(--deep-pink);
            text-align: center;
            border-bottom: 2px solid var(--primary-pink);
            padding-bottom: 8px;
        }

        #modal-content {
            margin-bottom: 20px;
            line-height: 1.8;
            color: var(--deep-purple);
            max-height: 60vh;
            overflow-y: auto;
        }

        #modal-buttons {
            display: flex;
            gap: 10px;
            justify-content: center;
            flex-wrap: wrap;
        }

        .modal-button {
            padding: 10px 20px;
            border: none;
            border-radius: 20px;
            color: white;
            cursor: pointer;
            background: var(--gradient-pink);
            transition: all 0.3s ease;
            font-weight: bold;
            min-width: 70px;
        }

        .modal-button:hover {
            transform: translateY(-2px);
            box-shadow: 0 5px 15px var(--shadow-pink);
        }

        .modal-button.secondary {
            background: var(--gradient-gold);
            color: var(--deep-purple);
        }

        /* 工具提示样式 */
        #tooltip {
            position: absolute;
            display: none;
            padding: 12px;
            background: var(--deep-purple);
            color: white;
            border-radius: 10px;
            z-index: 2000;
            pointer-events: none;
            max-width: 250px;
            white-space: pre-wrap;
            border: 2px solid var(--primary-pink);
            box-shadow: 0 5px 20px rgba(255, 105, 180, 0.4);
            animation: tooltipAppear 0.2s ease;
            font-size: 0.9em;
        }

        @keyframes tooltipAppear {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
        }

        /* 移动设备适配 */
        @media (max-width: 768px) {
            #game-container {
                margin: 5px;
                border-radius: 15px;
                max-width: 98vw;
            }

            .nav-icons-group {
                gap: 6px;
            }

            .nav-button {
                width: 40px;
                height: 40px;
            }

            .nav-button i {
                font-size: 16px;
            }

            #main-content-area {
                padding: 15px;
            }

            .status-layout {
                flex-direction: column;
                height: auto;
            }

            .status-sidebar {
                flex: none;
                order: -1;
                display: flex;
                flex-direction: row;
                overflow-x: auto;
                padding: 10px;
            }

            .char-selector {
                flex: 0 0 auto;
                margin-right: 10px;
                margin-bottom: 0;
            }

            .item-grid {
                grid-template-columns: repeat(auto-fill, minmax(100px, 1fr));
                gap: 10px;
            }

            .item-card {
                min-height: 120px;
                padding: 10px;
            }

            .item-icon {
                font-size: 28px;
            }

            .list-item {
                flex-direction: column;
                text-align: center;
                gap: 10px;
            }

            .list-item-icon {
                margin-right: 0;
                margin-bottom: 10px;
            }

            .list-item-action {
                align-items: center;
            }

            .calendar-grid {
                gap: 4px;
            }

            .calendar-day {
                font-size: 0.8em;
            }

            h1 {
                font-size: 1.8em;
            }

            h2 {
                font-size: 1.5em;
            }

            .choice-button {
                font-size: 0.9em;
                padding: 12px;
            }
        }

        @media (max-width: 480px) {
            #game-container {
                margin: 2px;
                max-width: 99vw;
            }

            #main-content-area {
                padding: 10px;
            }

            .item-grid {
                grid-template-columns: repeat(auto-fill, minmax(80px, 1fr));
            }

            .item-card {
                min-height: 100px;
                padding: 8px;
            }

            .item-icon {
                font-size: 24px;
            }

            .item-name {
                font-size: 0.8em;
            }

            .nav-button {
                width: 35px;
                height: 35px;
            }

            .nav-button i {
                font-size: 14px;
            }
        }

        /* 特殊动画效果 */
        .sparkle {
            position: relative;
        }

        .sparkle::after {
            content: '✨';
            position: absolute;
            top: -5px;
            right: -5px;
            animation: sparkleFloat 3s infinite;
            opacity: 0.7;
        }

        @keyframes sparkleFloat {
            0%, 100% {
                transform: translateY(0) rotate(0deg);
                opacity: 0.7;
            }
            50% {
                transform: translateY(-10px) rotate(180deg);
                opacity: 1;
            }
        }

        .rose-petals {
            position: fixed;
            top: -10px;
            left: 0;
            width: 100%;
            height: 100%;
            pointer-events: none;
            z-index: 1;
        }

        .petal {
            position: absolute;
            width: 8px;
            height: 8px;
            background: var(--primary-pink);
            border-radius: 50% 0 50% 0;
            animation: fallDown 8s linear infinite;
            opacity: 0.6;
        }

        @keyframes fallDown {
            0% {
                transform: translateY(-100px) rotate(0deg);
                opacity: 0.8;
            }
            100% {
                transform: translateY(100vh) rotate(360deg);
                opacity: 0;
            }
        }

        /* 错误处理样式 */
        .error-container {
            background: #ffebee;
            border: 2px solid #f44336;
            border-radius: 10px;
            padding: 20px;
            text-align: center;
            color: #c62828;
        }

        .loading-container {
            display: flex;
            justify-content: center;
            align-items: center;
            height: 200px;
            flex-direction: column;
            gap: 10px;
        }

        .loading-spinner {
            width: 40px;
            height: 40px;
            border: 4px solid var(--primary-pink);
            border-top: 4px solid transparent;
            border-radius: 50%;
            animation: spin 1s linear infinite;
        }

        @keyframes spin {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
        }
    </style>
</head>
<body>
    <textarea id="xml-data-source" style="display:none;">$1</textarea>
    <div id="tooltip" style="display: none;"></div>
    <div id="modal-overlay">
        <div id="modal-box">
            <h2 id="modal-title"></h2>
            <div id="modal-content"></div>
            <div id="modal-buttons"></div>
        </div>
    </div>

    <div class="rose-petals" id="rose-petals"></div>

    <div id="game-container">
        <div class="shortcut-bar top-bar"></div>
        <div id="main-content-area">
            <div id="page-home" class="page"></div>
            <div id="page-status" class="page"></div>
            <div id="page-calendar" class="page"></div>
            <div id="page-diary" class="page"></div>
            <div id="page-warehouse" class="page"></div>
            <div id="page-shop" class="page"></div>
            <div id="page-garden" class="page"></div>
            <div id="page-teatime" class="page"></div>
            <div id="page-lesson" class="page"></div>
            <div id="page-pet" class="page"></div>
            <div id="page-talent" class="page"></div>
        </div>
        <div id="player-choices-wrapper" style="display: none;">
            <div class="choices-header">
                <span></span>
                <span class="toggle-icon">💖</span>
            </div>
            <div id="player-choices-container">
                <div class="choices-inner"></div>
            </div>
        </div>
    </div>

    <script>
    (function() {
        let gameData = {}, gameState = {}, userActionLog = [];

        const logAction = (type, details) => {
            userActionLog.push({
                timestamp: new Date().toISOString(),
                type,
                details
            });
            console.log(`[User Action] ${type}:`, details);
        };

        // 增强的文本解析函数，支持桃华特色
        const parseText = text => {
            if (!text) return '';

            return text.toString()
                .replace(/\*\*(.*?)\*\*/g, (match, group1) => `<span class="highlight">${group1}</span>`)
                .replace(/\*(.*?)\*/g, (match, group1) => `<strong>${group1}</strong>`)
                .replace(/_(.*?)_/g, (match, group1) => `<em>${group1}</em>`)
                .replace(/~(.*?)~/g, (match, group1) => `<span class="whisper">${group1}</span>`)
                .replace(/ですわ/g, '<span class="deswa-text">ですわ</span>')
                .replace(/deswa/g, '<span class="deswa-text">deswa</span>')
                .replace(/<ruby>(.*?)<rt>(.*?)<\/rt><\/ruby>/g, (match, p1, p2) => `<ruby class="ruby-text">${p1}<rt>${p2}</rt></ruby>`)
                .replace(/\\n/g, '<br>')
                .replace(/\n/g, '<br>');
        };

        const extractCdata = node => node ? (Array.from(node.childNodes)
            .find(c => c.nodeType === 4)?.nodeValue.trim() || node.textContent.trim()) : '';

        const getAttr = (node, attrName, dv = '') => node ?
            node.getAttribute(attrName) || dv : dv;

        // 增强的错误处理
        const handleError = (error, context) => {
            console.error(`Error in ${context}:`, error);
            logAction('系统错误', { context, error: error.message });
        };

        window.handleChoiceClick = function(choiceText) {
            if (typeof window.triggerSlash !== 'function') {
                return console.error("API 'triggerSlash' 未找到");
            }

            const logXml = userActionLog.length > 0 ?
                `<用户操作记录>${userActionLog.map(log =>
                    `<操作 类型="${log.type}" 时间="${log.timestamp}"><![CDATA[${JSON.stringify(log.details)}]]></操作>`
                ).join('')}</用户操作记录>` : '';

            const msg = `${choiceText}${logXml ? `\n\n${logXml}` : ''}`;

            try {
                window.triggerSlash(`/send 【USER】 [选择] ${msg}|/trigger`);
                userActionLog = [];
                document.getElementById('player-choices-wrapper').style.display = 'none';
            } catch (error) {
                handleError(error, 'handleChoiceClick');
            }
        };

        function parseXmlData(xmlDoc) {
            const data = {};
            const getText = (sel, dv = '') => {
                try {
                    return xmlDoc.querySelector(sel)?.textContent.trim() || dv;
                } catch (e) {
                    console.warn(`Failed to get text for selector: ${sel}`, e);
                    return dv;
                }
            };

            function parseStatusElement(elementNode, depth = 0) {
                if (!elementNode) return null;

                const label = elementNode.nodeName.replace(/_/g, ' ');
                const attributes = {
                    current: getAttr(elementNode, '当前值', null),
                    max: getAttr(elementNode, '最大值', null),
                    unit: getAttr(elementNode, '单位', '')
                };

                const childElements = Array.from(elementNode.children);
                let value = null;
                let nestedChildren = [];

                if (childElements.length > 0) {
                    nestedChildren = childElements.map(child =>
                        parseStatusElement(child, depth + 1)
                    ).filter(Boolean);
                } else {
                    value = extractCdata(elementNode);
                }

                if (attributes.current !== null) {
                    value = attributes.current;
                }

                return {
                    label: label,
                    value: value,
                    current: attributes.current,
                    max: attributes.max,
                    unit: attributes.unit,
                    children: nestedChildren.length > 0 ? nestedChildren : null,
                    depth: depth
                };
            }

            try {
                data.config = {
                    title: getText('窗口标题'),
                    choiceHeader: getText('选择区标题')
                };

                data.nav = Array.from(xmlDoc.querySelectorAll('导航栏 > 分组')).map(g => ({
                    position: getAttr(g, '位置'),
                    buttons: Array.from(g.querySelectorAll('按钮')).map(b => ({
                        id: getAttr(b, 'id'),
                        title: getAttr(b, '标题'),
                        iconHTML: `<i class="${getText(`按钮[id="${getAttr(b,'id')}"] > 图标`)}"></i>`
                    }))
                }));

                data.initialScene = {
                    homeContent: extractCdata(xmlDoc.querySelector('初始场景 > 主页内容')),
                    choices: Array.from(xmlDoc.querySelectorAll('初始场景 > 玩家选项 > 选项')).map(opt => ({
                        text: extractCdata(opt)
                    }))
                };

                data.characters = Array.from(xmlDoc.querySelectorAll('角色列表 > 角色')).map(cNode => {
                    const charId = getAttr(cNode, 'id');
                    return {
                        id: charId,
                        name: getText(`角色[id="${charId}"] > 名称`),
                        avatar: getText(`角色[id="${charId}"] > 头像`),
                        intro: getText(`角色[id="${charId}"] > 简介`),
                        status: Array.from(cNode.children)
                                   .filter(n => !['名称', '头像', '简介'].includes(n.nodeName))
                                   .map(statusGroupNode => ({
                                       label: statusGroupNode.nodeName.replace(/_/g, ' '),
                                       children: Array.from(statusGroupNode.children)
                                                    .map(elem => parseStatusElement(elem))
                                                    .filter(Boolean)
                                   }))
                    };
                });

                // 解析新增页面数据
                const gardenNode = xmlDoc.querySelector('玫瑰花园');
                if (gardenNode) {
                    data.garden = {
                        description: extractCdata(gardenNode.querySelector('花园描述')),
                        roses: Array.from(gardenNode.querySelectorAll('玫瑰品种 > 玫瑰')).map(r => ({
                            id: getAttr(r, 'id'),
                            name: getText(`玫瑰[id="${getAttr(r, 'id')}"] > 名称`),
                            icon: getText(`玫瑰[id="${getAttr(r, 'id')}"] > 图标`),
                            color: getText(`玫瑰[id="${getAttr(r, 'id')}"] > 颜色`),
                            meaning: getText(`玫瑰[id="${getAttr(r, 'id')}"] > 花语`),
                            quantity: parseInt(getText(`玫瑰[id="${getAttr(r, 'id')}"] > 数量`), 10),
                            status: getText(`玫瑰[id="${getAttr(r, 'id')}"] > 生长状态`),
                            description: extractCdata(r.querySelector('描述'))
                        })),
                        activities: Array.from(gardenNode.querySelectorAll('花园活动 > 活动')).map(a => ({
                            id: getAttr(a, 'id'),
                            name: getText(`活动[id="${getAttr(a, 'id')}"] > 名称`),
                            description: getText(`活动[id="${getAttr(a, 'id')}"] > 描述`),
                            effect: getText(`活动[id="${getAttr(a, 'id')}"] > 效果`)
                        }))
                    };
                }

                const teatimeNode = xmlDoc.querySelector('下午茶会');
                if (teatimeNode) {
                    data.teatime = {
                        description: extractCdata(teatimeNode.querySelector('茶会描述')),
                        teas: Array.from(teatimeNode.querySelectorAll('茶水菜单 > 茶饮')).map(t => ({
                            id: getAttr(t, 'id'),
                            name: getText(`茶饮[id="${getAttr(t, 'id')}"] > 名称`),
                            icon: getText(`茶饮[id="${getAttr(t, 'id')}"] > 图标`),
                            type: getText(`茶饮[id="${getAttr(t, 'id')}"] > 类型`),
                            temperature: getText(`茶饮[id="${getAttr(t, 'id')}"] > 温度`),
                            price: getText(`茶饮[id="${getAttr(t, 'id')}"] > 价格`),
                            description: extractCdata(t.querySelector('描述')),
                            effect: getText(`茶饮[id="${getAttr(t, 'id')}"] > 效果`)
                        })),
                        desserts: Array.from(teatimeNode.querySelectorAll('点心菜单 > 点心')).map(d => ({
                            id: getAttr(d, 'id'),
                            name: getText(`点心[id="${getAttr(d, 'id')}"] > 名称`),
                            icon: getText(`点心[id="${getAttr(d, 'id')}"] > 图标`),
                            type: getText(`点心[id="${getAttr(d, 'id')}"] > 类型`),
                            ingredients: getText(`点心[id="${getAttr(d, 'id')}"] > 配料`),
                            price: getText(`点心[id="${getAttr(d, 'id')}"] > 价格`),
                            description: extractCdata(d.querySelector('描述'))
                        })),
                        activities: Array.from(teatimeNode.querySelectorAll('茶会活动 > 活动')).map(a => ({
                            id: getAttr(a, 'id'),
                            name: getText(`活动[id="${getAttr(a, 'id')}"] > 名称`),
                            description: getText(`活动[id="${getAttr(a, 'id')}"] > 描述`)
                        }))
                    };
                }

                const lessonNode = xmlDoc.querySelector('家庭教师课程');
                if (lessonNode) {
                    data.lessons = {
                        description: extractCdata(lessonNode.querySelector('课程描述')),
                        courses: Array.from(lessonNode.querySelectorAll('课程列表 > 课程')).map(c => ({
                            id: getAttr(c, 'id'),
                            name: getText(`课程[id="${getAttr(c, 'id')}"] > 名称`),
                            icon: getText(`课程[id="${getAttr(c, 'id')}"] > 图标`),
                            type: getText(`课程[id="${getAttr(c, 'id')}"] > 类型`),
                            difficulty: getText(`课程[id="${getAttr(c, 'id')}"] > 难度`),
                            duration: getText(`课程[id="${getAttr(c, 'id')}"] > 时长`),
                            description: extractCdata(c.querySelector('描述')),
                            content: Array.from(c.querySelectorAll('内容 > 要点')).map(p => p.textContent.trim()),
                            progress: (() => {
                                const progressNode = lessonNode.querySelector(`教学进度 > 进度[课程id="${getAttr(c, 'id')}"]`);
                                return progressNode ? {
                                    completion: parseInt(getAttr(progressNode, '完成度'), 10),
                                    grade: getAttr(progressNode, '等级')
                                } : { completion: 0, grade: '未开始' };
                            })()
                        }))
                    };
                }

                const petNode = xmlDoc.querySelector('宠物照顾');
                if (petNode) {
                    data.pets = {
                        description: extractCdata(petNode.querySelector('宠物描述')),
                        pets: Array.from(petNode.querySelectorAll('宠物列表 > 宠物')).map(p => ({
                            id: getAttr(p, 'id'),
                            name: getText(`宠物[id="${getAttr(p, 'id')}"] > 名称`),
                            chineseName: getText(`宠物[id="${getAttr(p, 'id')}"] > 中文名`),
                            icon: getText(`宠物[id="${getAttr(p, 'id')}"] > 图标`),
                            breed: getText(`宠物[id="${getAttr(p, 'id')}"] > 品种`),
                            age: getText(`宠物[id="${getAttr(p, 'id')}"] > 年龄`),
                            personality: getText(`宠物[id="${getAttr(p, 'id')}"] > 性格`),
                            health: getText(`宠物[id="${getAttr(p, 'id')}"] > 健康状态`),
                            mood: getText(`宠物[id="${getAttr(p, 'id')}"] > 心情`),
                            hunger: (() => {
                                const hungerNode = p.querySelector('饥饿度');
                                return hungerNode ? {
                                    current: parseInt(getAttr(hungerNode, '当前值'), 10),
                                    max: parseInt(getAttr(hungerNode, '最大值'), 10),
                                    status: hungerNode.textContent.trim()
                                } : null;
                            })(),
                            cleanliness: (() => {
                                const cleanNode = p.querySelector('清洁度');
                                return cleanNode ? {
                                    current: parseInt(getAttr(cleanNode, '当前值'), 10),
                                    max: parseInt(getAttr(cleanNode, '最大值'), 10),
                                    status: cleanNode.textContent.trim()
                                } : null;
                            })(),
                            happiness: (() => {
                                const happyNode = p.querySelector('快乐度');
                                return happyNode ? {
                                    current: parseInt(getAttr(happyNode, '当前值'), 10),
                                    max: parseInt(getAttr(happyNode, '最大值'), 10),
                                    status: happyNode.textContent.trim()
                                } : null;
                            })(),
                            description: extractCdata(p.querySelector('描述')),
                            habits: Array.from(p.querySelectorAll('特殊癖好 > 癖好')).map(h => h.textContent.trim())
                        })),
                        activities: Array.from(petNode.querySelectorAll('照顾活动 > 活动')).map(a => ({
                            id: getAttr(a, 'id'),
                            name: getText(`活动[id="${getAttr(a, 'id')}"] > 名称`),
                            icon: getText(`活动[id="${getAttr(a, 'id')}"] > 图标`),
                            description: getText(`活动[id="${getAttr(a, 'id')}"] > 描述`),
                            effect: getText(`活动[id="${getAttr(a, 'id')}"] > 效果`),
                            time: getText(`活动[id="${getAttr(a, 'id')}"] > 所需时间`)
                        }))
                    };
                }

                const talentNode = xmlDoc.querySelector('才艺展示');
                if (talentNode) {
                    data.talents = {
                        description: extractCdata(talentNode.querySelector('展示描述')),
                        talents: Array.from(talentNode.querySelectorAll('才艺列表 > 才艺')).map(t => ({
                            id: getAttr(t, 'id'),
                            name: getText(`才艺[id="${getAttr(t, 'id')}"] > 名称`),
                            icon: getText(`才艺[id="${getAttr(t, 'id')}"] > 图标`),
                            type: getText(`才艺[id="${getAttr(t, 'id')}"] > 类型`),
                            difficulty: getText(`才艺[id="${getAttr(t, 'id')}"] > 难度`),
                            duration: getText(`才艺[id="${getAttr(t, 'id')}"] > 表演时长`),
                            proficiency: getText(`才艺[id="${getAttr(t, 'id')}"] > 熟练度`),
                            description: extractCdata(t.querySelector('描述')),
                            content: Array.from(t.querySelectorAll('表演内容 > 片段')).map(s => s.textContent.trim()),
                            reaction: getText(`才艺[id="${getAttr(t, 'id')}"] > 观众反应`)
                        })),
                        schedule: Array.from(talentNode.querySelectorAll('表演安排 > 时段')).map(s => ({
                            time: getAttr(s, '时间'),
                            talent: getAttr(s, '才艺'),
                            audience: getAttr(s, '观众')
                        }))
                    };
                }

                // 解析其他现有数据...
                const calendarNode = xmlDoc.querySelector('寸止日历');
                if (calendarNode) {
                    data.calendar = {
                        currentDate: getText('寸止日历 > 当前日期'),
                        plans: Array.from(calendarNode.querySelectorAll('训练计划 > 日期')).map(d => ({
                            date: getAttr(d, '时间'),
                            course: getText(`日期[时间="${getAttr(d, '时间')}"] > 课程`),
                            targetCount: parseInt(getText(`日期[时间="${getAttr(d, '时间')}"] > 目标次数`), 10),
                            status: getText(`日期[时间="${getAttr(d, '时间')}"] > 完成状态`),
                            reward: getText(`日期[时间="${getAttr(d, '时间')}"] > 奖励`)
                        }))
                    };
                }

                const diaryNode = xmlDoc.querySelector('调教日志');
                if (diaryNode) {
                    data.diary = {
                        entries: Array.from(diaryNode.querySelectorAll('记录')).map(r => ({
                            id: getAttr(r, 'id'),
                            time: getAttr(r, '时间'),
                            course: getText(`记录[id="${getAttr(r, 'id')}"] > 课程`),
                            content: extractCdata(r.querySelector('内容')),
                            evaluation: getText(`记录[id="${getAttr(r, 'id')}"] > 评价`),
                            momokaComment: extractCdata(r.querySelector('桃华点评'))
                        }))
                    };
                }

                const warehouseNode = xmlDoc.querySelector('仓库');
                if (warehouseNode) {
                    data.warehouse = {
                        items: Array.from(warehouseNode.querySelectorAll('物品')).map(i => ({
                            item: {
                                id: getAttr(i, 'id'),
                                name: i.querySelector('名称').textContent.trim(),
                                icon: i.querySelector('图标').textContent.trim(),
                                description: extractCdata(i.querySelector('描述'))
                            },
                            quantity: parseInt(getAttr(i, '数量'), 10)
                        }))
                    };
                }

                const shopNode = xmlDoc.querySelector('商店');
                if (shopNode) {
                    data.shop = {
                        currency: getText('商店 > 货币', '💎'),
                        funds: parseInt(getText('商店 > 资金'), 10),
                        items: Array.from(shopNode.querySelectorAll('物品')).map(i => ({
                            id: getAttr(i, 'id'),
                            price: parseInt(getAttr(i, '价格'), 10),
                            name: i.querySelector('名称').textContent.trim(),
                            icon: i.querySelector('图标').textContent.trim(),
                            description: extractCdata(i.querySelector('描述'))
                        }))
                    };
                }

            } catch (error) {
                handleError(error, 'parseXmlData');
                throw error;
            }

            return data;
        }

        const showModal = ({ title, content, buttons }) => {
            document.getElementById('modal-title').innerHTML = parseText(title);
            document.getElementById('modal-content').innerHTML = parseText(content);
            const btnContainer = document.getElementById('modal-buttons');
            btnContainer.innerHTML = '';
            buttons.forEach(btn => {
                const btnEl = document.createElement('button');
                btnEl.textContent = btn.text;
                btnEl.className = `modal-button ${btn.class || ''}`;
                btnEl.onclick = () => {
                    if (btn.action) btn.action();
                    hideModal();
                };
                btnContainer.appendChild(btnEl);
            });
            document.getElementById('modal-overlay').style.display = 'flex';
        };

        const hideModal = () => document.getElementById('modal-overlay').style.display = 'none';

        const showPage = (id) => {
            document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
            document.getElementById(`page-${id}`).classList.add('active');
            document.querySelectorAll('.nav-button').forEach(b =>
                b.classList.toggle('active', b.dataset.page === id));

            const renderer = {
                home: renderHomePage,
                status: renderStatusPage,
                calendar: renderCalendarPage,
                diary: renderDiaryPage,
                warehouse: renderWarehousePage,
                shop: renderShopPage,
                garden: renderGardenPage,
                teatime: renderTeatimePage,
