        function renderPetPage() {
            const page = document.getElementById('page-pet');

            if (!gameData.pets) {
                page.innerHTML = `
                    <h2>🐕 宠物照顾 🐕</h2>
                    <div class="page-container">
                        <p>暂无宠物数据</p>
                    </div>`;
