            }

            const petsHTML = gameData.pets.pets.map(pet => `
                <div class="list-item">
                    <div class="list-item-icon" style="font-size: 48px;">${pet.icon}</div>
                    <div class="list-item-info">
                        <strong>${pet.name} (${pet.chineseName})</strong>
                        <p><strong>品种：</strong>${pet.breed} | <strong>年龄：</strong>${pet.age} | <strong>性格：</strong>${pet.personality}</p>
                        <p><strong>心情：</strong>${pet.mood} | <strong>健康：</strong>${pet.health}</p>
