                // 渲染系统日志
                const choiceMatch = rawInput.match(/\[选择\]\s*([\s\S]*?)(?=<用户操作记录>|\n\n|$)/);
                const choiceText = choiceMatch ? choiceMatch[1].trim() : '执行桃华的指示';

                let logContentHTML = '';
                const logXmlMatch = rawInput.match(/<用户操作记录>([\s\S]*?)<\/用户操作记录>/);

                if (logXmlMatch) {
                    try {
                        const parser = new DOMParser();
                        const xmlDoc = parser.parseFromString(`<root>${logXmlMatch[1]}</root>`, "application/xml");
                        const operations = xmlDoc.querySelectorAll('操作');

                        if (operations.length === 0 && logXmlMatch[1].trim() !== '') {
                            logContentHTML = `解析遇到困难，原始记录：<br><pre style="font-size:0.8em;opacity:0.7;">${logXmlMatch[1].replace(/</g, "&lt;").replace(/>/g, "&gt;")}</pre>`;
                        } else if (operations.length === 0) {
                            logContentHTML = '<div class="log-entry">本次互动暂无详细操作记录</div>';
                        }

                        operations.forEach(op => {
                            const type = op.getAttribute('类型') || '未知操作';
                            const timestampAttr = op.getAttribute('时间');
                            const timestamp = timestampAttr ?
                                new Date(timestampAttr).toLocaleTimeString('zh-CN', {
                                    hour: '2-digit',
                                    minute: '2-digit',
                                    second: '2-digit',
                                    hour12: false
                                }) : '??:??:??';
                            const cdata = op.textContent.trim();
                            let details = '';

                            try {
                                const jsonData = JSON.parse(cdata);
                                switch(type) {
                                    case '购买道具':
                                        details = `道具: <strong>${jsonData.itemName || jsonData.name}</strong> ${jsonData.itemId ? `(ID: ${jsonData.itemId})` : ''}, 花费: ${jsonData.price || '未知'}`;
                                        break;
                                    case '使用道具':
                                        details = `使用道具: <strong>${jsonData.itemName}</strong> ${jsonData.itemId ? `(ID: ${jsonData.itemId})` : ''}`;
                                        break;
                                    case '查看道具详情':
                                    case '查看玫瑰详情':
                                    case '查看课程详情':
                                    case '查看日志详情':
                                    case '查看日历计划':
                                        details = `查看详情: <strong>${jsonData.itemName || jsonData.roseName || jsonData.courseName || jsonData.entryId || '未知'}</strong>`;
                                        break;
                                    case '花园活动':
                                        details = `花园活动: <strong>${jsonData.activityName}</strong>`;
                                        break;
                                    case '宠物活动':
                                        details = `宠物活动: <strong>${jsonData.activityName}</strong>`;
                                        break;
                                    case '照顾宠物':
                                        details = `照顾宠物: <strong>${jsonData.petName}</strong>`;
                                        break;
                                    case '观看才艺':
                                        details = `观看才艺: <strong>${jsonData.talentName}</strong>`;
                                        break;
                                    case '选择茶饮':
                                        details = `选择茶饮: <strong>${jsonData.teaName}</strong>`;
                                        break;
                                    case '选择点心':
                                        details = `选择点心: <strong>${jsonData.dessertName}</strong>`;
                                        break;
                                    case '系统错误':
                                        details = `错误上下文: <strong>${jsonData.context}</strong>, 错误信息: ${jsonData.error}`;
                                        break;
                                    default:
                                        details = Object.entries(jsonData)
                                            .map(([key, value]) => `${key}: ${typeof value === 'object' ? JSON.stringify(value) : value}`)
                                            .join(', ');
                                        break;
                                }
                            } catch (e) {
                                details = cdata || '无详细信息';
                            }

                            logContentHTML += `<div class="log-entry" data-type="${type}">
                                <span class="log-timestamp">[${timestamp}]</span>
                                <span class="log-type">${type}:</span>
                                <span class="log-details">${details}</span>
                            </div>`;
                        });
                    } catch (e) {
                        console.error("解析操作记录XML时出错:", e);
                        logContentHTML = '<div class="log-entry">操作记录解析失败</div>';
                    }
                } else if (choiceText !== '执行桃华的指示' && choiceText !== '') {
                    logContentHTML = '<div class="log-entry">本次选择无附加操作日志</div>';
                }

                container.innerHTML = `
                    <div class="styler-wrapper system-log-card">
                        <div class="header">
                            <i class="fas fa-crown"></i>
                            桃华的管教记录: ${choiceText}
                        </div>
                        <div class="content">${logContentHTML || '<div class="log-entry">暂无操作记录</div>'}</div>
                    </div>
                `;

            } else {
                // 渲染用户输入
                let processedInput = rawInput
                    .replace(/</g, "&lt;")
                    .replace(/>/g, "&gt;")
                    .replace(/\n/g, "<br>");

                // 特殊格式处理
                processedInput = processedInput
                    .replace(/\*\*(.*?)\*\*/g, (match, group1) => `<span style="background: var(--gradient-gold); color: var(--momoka-purple); padding: 2px 6px; border-radius: 8px; font-weight: bold;">${group1}</span>`)
                    .replace(/\*(.*?)\*/g, (match, group1) => `<strong>${group1}</strong>`)
                    .replace(/_(.*?)_/g, (match, group1) => `<em>${group1}</em>`)
                    .replace(/(ですわ|deswa)/g, (match, group1) => `<span style="color: var(--momoka-deep-pink); font-weight: bold; position: relative;">${group1}<span style="position: absolute; top: -2px; right: -15px; font-size: 0.8em; opacity: 0.7;">✨</span></span>`);

                container.innerHTML = `
                    <div class="styler-wrapper user-input-card">
                        <div class="header">
                            <i class="fas fa-heart"></i>
                            您向桃华妈妈的倾诉
                        </div>
                        <div class="content">${processedInput}</div>
                    </div>
                `;
            }
        })();
    </script>
</body>
</html>
