                                    max: parseInt(getAttr(hungerNode, '最大值'), 10),
                                    status: hungerNode.textContent.trim()
                                } : null;
                            })(),
                            cleanliness: (() => {
                                const cleanNode = p.querySelector('清洁度');
                                return cleanNode ? {
                                    current: parseInt(getAttr(cleanNode, '当前值'), 10),
                                    max: parseInt(getAttr(cleanNode, '最大值'), 10),
                                    status: cleanNode.textContent.trim()
                                } : null;
                            })(),
                            happiness: (() => {
                                const happyNode = p.querySelector('快乐度');
                                return happyNode ? {
