            } catch (error) {
                handleError(error, 'parseXmlData');
                throw error;
            }

            return data;
        }

        const showModal = ({ title, content, buttons }) => {
            document.getElementById('modal-title').innerHTML = parseText(title);
            document.getElementById('modal-content').innerHTML = parseText(content);
            const btnContainer = document.getElementById('modal-buttons');
            btnContainer.innerHTML = '';
            buttons.forEach(btn => {
                const btnEl = document.createElement('button');
                btnEl.textContent = btn.text;
                btnEl.className = `modal-button ${btn.class || ''}`;
                btnEl.onclick = () => {
                    if (btn.action) btn.action();
                    hideModal();
                };
                btnContainer.appendChild(btnEl);
            });
            document.getElementById('modal-overlay').style.display = 'flex';
        };

        const hideModal = () => document.getElementById('modal-overlay').style.display = 'none';

        const showPage = (id) => {
            document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
            document.getElementById(`page-${id}`).classList.add('active');
            document.querySelectorAll('.nav-button').forEach(b =>
                b.classList.toggle('active', b.dataset.page === id));

            const renderer = {
                home: renderHomePage,
                status: renderStatusPage,
                calendar: renderCalendarPage,
                diary: renderDiaryPage,
                warehouse: renderWarehousePage,
                shop: renderShopPage,
                garden: renderGardenPage,
                teatime: renderTeatimePage,
                lesson: renderLessonPage,
                pet: renderPetPage,
                talent: renderTalentPage
            }[id];

            if (renderer) {
                try {
                    renderer();
                } catch (error) {
                    handleError(error, `render${id}Page`);
                    document.getElementById(`page-${id}`).innerHTML = `
                        <div class="error-container">
                            <h3>页面加载失败</h3>
                            <p>抱歉，${id}页面暂时无法显示。</p>
                        </div>`;
                }
            }
        };

        const renderHomePage = () => {
            document.getElementById('page-home').innerHTML = `
                <h1 class="sparkle">桃华妈妈的私密花园</h1>
                <div class="home-content">
                    ${parseText(gameData.initialScene.homeContent)}
                </div>
            `;
        };

        function renderStatusPage() {
            const page = document.getElementById('page-status');

            function renderStatusItemHTML(item) {
                if (item.current !== null && item.max !== null && parseFloat(item.max) > 0) {
                    const percentage = Math.max(0, Math.min(100,
                        (parseFloat(item.current) / parseFloat(item.max)) * 100));

                    let barClass = 'progress-bar-inner';
                    if (item.label.includes('好感度')) barClass += ' affection-bar';
                    else if (item.label.includes('支配力')) barClass += ' dominance-bar';
                    else if (item.label.includes('母性')) barClass += ' maternal-bar';
                    else if (item.label.includes('优雅度')) barClass += ' elegance-bar';

                    return `
                        <div class="status-item progress-bar-item">
                            <div class="progress-bar" title="${item.label}">
                                <div class="progress-bar-text">${item.label}: ${item.current} / ${item.max}${item.unit || ''}</div>
                                <div class="${barClass}" style="width:${percentage}%"></div>
                            </div>
                        </div>`;
                } else if (item.children && item.children.length > 0) {
                    return `
                        <div class="status-item nested" style="margin-left: ${item.depth * 10}px;">
                            <strong class="status-label">${item.label}:</strong>
                            <div class="status-nested-content">
                                ${item.children.map(child => renderStatusItemHTML(child)).join('')}
                            </div>
                        </div>`;
                } else {
                    const displayValue = item.value !== null && typeof item.value !== 'undefined' ?
                        item.value : 'N/A';
                    return `
                        <div class="status-item" style="margin-left: ${(item.depth || 0) * 10}px;">
                            <span class="status-label">${item.label}:</span>
                            <span class="status-value">${parseText(displayValue)}</span>
                        </div>`;
                }
            }

            const renderStatusGroupHTML = (statusGroups) => statusGroups.map(group => `
                <div class="status-block">
                    <h4>${group.label}</h4>
                    ${group.children.map(item => renderStatusItemHTML(item)).join('')}
                </div>
            `).join('');

            const sidebarHTML = gameData.characters.map((charData, i) =>
                `<div class="char-selector ${i === 0 ? 'active' : ''}" data-char-id="${charData.id}">
                    <div class="char-avatar">${charData.avatar}</div>
                    <span class="char-name">${charData.name}</span>
                </div>`
            ).join('');

            const contentHTML = gameData.characters.map((charData, i) => `
                <div class="status-card ${i === 0 ? 'active' : ''}" data-char-id="${charData.id}">
                    <p class="char-intro">${parseText(charData.intro)}</p>
                    ${renderStatusGroupHTML(charData.status)}
                </div>`).join('');

            page.innerHTML = `
                <h2>✨ 状态总览 ✨</h2>
                <div class="status-layout">
                    <div class="status-sidebar">${sidebarHTML}</div>
                    <div class="status-content-area">${contentHTML}</div>
                </div>`;

            page.querySelector('.status-sidebar').addEventListener('click', (e) => {
                const selector = e.target.closest('.char-selector');
                if (!selector) return;
                const id = selector.dataset.charId;
                page.querySelectorAll('.char-selector, .status-card').forEach(el =>
                    el.classList.remove('active'));
                selector.classList.add('active');
                const cardToShow = page.querySelector(`.status-card[data-char-id="${id}"]`);
                if (cardToShow) cardToShow.classList.add('active');
            });
        }

        function renderCalendarPage() {
            const page = document.getElementById('page-calendar');

            if (!gameData.calendar) {
                page.innerHTML = `
                    <h2>💖 寸止禁欲日历 💖</h2>
                    <div class="page-container">
                        <p>暂无日历数据</p>
                    </div>`;
                return;
            }

            const currentDate = new Date(gameData.calendar.currentDate);
            const year = currentDate.getFullYear();
            const month = currentDate.getMonth();

            const firstDay = new Date(year, month, 1);
            const lastDay = new Date(year, month + 1, 0);
            const startDate = new Date(firstDay);
            startDate.setDate(startDate.getDate() - firstDay.getDay());

            const calendarDays = [];
            const currentDateStr = gameData.calendar.currentDate;

            for (let d = new Date(startDate); d <= lastDay; d.setDate(d.getDate() + 1)) {
                const dateStr = d.toISOString().split('T')[0];
                const plan = gameData.calendar.plans.find(p => p.date === dateStr);
                const isToday = dateStr === currentDateStr;
                const isCurrentMonth = d.getMonth() === month;

                let dayClass = 'calendar-day';
                if (plan) {
                    dayClass += ' has-training';
                    if (plan.status === '已完成') dayClass += ' completed';
                }
                if (isToday) dayClass += ' today';
                if (!isCurrentMonth) dayClass += ' other-month';

                calendarDays.push(`
                    <div class="${dayClass}" data-date="${dateStr}" data-plan='${plan ? JSON.stringify(plan) : ''}'>
                        <div class="day-number">${d.getDate()}</div>
                        ${plan ? `<div class="day-indicator">📅</div>` : ''}
                    </div>`);
            }

            page.innerHTML = `
                <h2>💖 寸止禁欲日历 💖</h2>
                <div class="page-container">
                    <h3>${year}年${month + 1}月</h3>
                    <div class="calendar-grid">
                        <div class="calendar-header">日</div>
                        <div class="calendar-header">一</div>
                        <div class="calendar-header">二</div>
                        <div class="calendar-header">三</div>
                        <div class="calendar-header">四</div>
                        <div class="calendar-header">五</div>
                        <div class="calendar-header">六</div>
                        ${calendarDays.join('')}
                    </div>
                </div>`;

            page.querySelector('.calendar-grid').addEventListener('click', (e) => {
                const dayEl = e.target.closest('.calendar-day');
                if (!dayEl || !dayEl.dataset.plan) return;

                const plan = JSON.parse(dayEl.dataset.plan);
                logAction('查看日历计划', { date: plan.date, course: plan.course });
                showModal({
                    title: `${plan.date} 训练计划`,
                    content: `
                        <strong>课程：</strong>${plan.course}<br>
                        <strong>目标次数：</strong>${plan.targetCount}次<br>
                        <strong>完成状态：</strong>${plan.status}<br>
                        <strong>奖励：</strong>${plan.reward}
                    `,
                    buttons: [{ text: '知道了' }]
                });
            });
        }

