            page.innerHTML = `
                <h2>🎀 道具收藏 🎀</h2>
                <div class="page-container">
                    <div class="item-grid">${itemsHTML}</div>
                </div>`;

            page.querySelectorAll('.item-card').forEach(el => {
                el.onclick = () => {
