                    logAction('查看道具详情', { itemName: slot.item.name, itemId: slot.item.id });
                    showModal({
                        title: slot.item.name,
                        content: parseText(slot.item.description),
                        buttons: [
                            { text: '使用', class: 'primary', action: () => {
                                logAction('使用道具', {
                                    itemName: slot.item.name,
                                    itemId: slot.item.id
                                });
                                showModal({
                                    title: '使用道具',
                                    content: '桃华会在合适的时候使用这个道具呢♪',
                                    buttons: [{ text: '期待中...' }]
                                });
                            }},
                            { text: '取消', class: 'secondary' }
                        ]
                    });
                };

                el.onmousemove = e => {
                    const slot = JSON.parse(el.dataset.item);
                    const tt = document.getElementById('tooltip');
                    tt.innerHTML = `<strong>${slot.item.name}</strong> (x${slot.quantity})<hr>${parseText(slot.item.description)}`;
                    tt.style.display = 'block';
                    tt.style.left = `${e.pageX + 15}px`;
                    tt.style.top = `${e.pageY + 15}px`;
