        function renderShopPage() {
            const page = document.getElementById('page-shop');

            if (!gameData.shop) {
                page.innerHTML = `
                    <h2>🛍️ 秘密商店 🛍️</h2>
                    <div class="page-container">
                        <p>暂无商店数据</p>
                    </div>`;
                return;
            }

            const currentMoney = gameState?.money !== undefined ? gameState.money : gameData.shop.funds;

            const itemsHTML = gameData.shop.items.map(item => {
                const canAfford = currentMoney >= item.price;
                return `
                    <div class="list-item">
                        <div class="list-item-icon">${item.icon}</div>
                        <div class="list-item-info">
                            <strong>${item.name}</strong>
                            <p>${parseText(item.description)}</p>
                        </div>
                        <div class="list-item-action">
                            <span class="price">${gameData.shop.currency} ${item.price}</span>
                            <button class="styled-button buy-button ${canAfford ? '' : 'disabled'}"
                                    data-item-id="${item.id}"
                                    ${canAfford ? '' : 'disabled'}>
                                ${canAfford ? '购买' : '资金不足'}
                            </button>
                        </div>
                    </div>`;
            }).join('');

            page.innerHTML = `
                <h2>🛍️ 秘密商店 🛍️</h2>
                <div class="page-container">
                    <div class="currency-display">当前资金：${gameData.shop.currency} ${currentMoney}</div>
                    <div class="item-list">${itemsHTML}</div>
                </div>`;

            page.querySelector('.item-list').addEventListener('click', (e) => {
                const button = e.target.closest('.buy-button');
                if (!button || button.disabled) return;

                const item = gameData.shop.items.find(i => i.id === button.dataset.itemId);
                if (!item) return;

                const currentMoney = gameState?.money !== undefined ? gameState.money : gameData.shop.funds;
                if (currentMoney < item.price) {
                    return showModal({
                        title: '资金不足',
                        content: '桃华妈妈说：「<ruby>お金が足りませんわ<rt>钱不够呢</rt></ruby>」',
                        buttons: [{ text: '遵命' }]
                    });
                }

                if (gameState.money !== undefined) {
                    gameState.money -= item.price;
                } else {
                    gameState.money = gameData.shop.funds - item.price;
                }

                const existingSlot = gameState.warehouse?.find(s => s.item.id === item.id);
                if (existingSlot) {
                    existingSlot.quantity++;
                } else {
                    if (!gameState.warehouse) gameState.warehouse = [];
                    gameState.warehouse.push({
                        item: { ...item },
                        quantity: 1
                    });
                }

