            if (!gameData.pets) {
                page.innerHTML = `
                    <h2>🐕 宠物照顾 🐕</h2>
                    <div class="page-container">
                        <p>暂无宠物数据</p>
                    </div>`;
                return;
            }

            const petsHTML = gameData.pets.pets.map(pet => `
                <div class="list-item">
                    <div class="list-item-icon" style="font-size: 48px;">${pet.icon}</div>
                    <div class="list-item-info">
                        <strong>${pet.name} (${pet.chineseName})</strong>
                        <p><strong>品种：</strong>${pet.breed} | <strong>年龄：</strong>${pet.age} | <strong>性格：</strong>${pet.personality}</p>
                        <p><strong>心情：</strong>${pet.mood} | <strong>健康：</strong>${pet.health}</p>
                        ${pet.hunger ? `<div class="progress-bar" style="margin: 5px 0;"><div class="progress-bar-text">饥饿度: ${pet.hunger.current}/${pet.hunger.max}</div><div class="progress-bar-inner" style="width: ${100 - (pet.hunger.current/pet.hunger.max)*100}%;"></div></div>` : ''}
                        ${pet.cleanliness ? `<div class="progress-bar" style="margin: 5px 0;"><div class="progress-bar-text">清洁度: ${pet.cleanliness.current}/${pet.cleanliness.max}</div><div class="progress-bar-inner elegance-bar" style="width: ${(pet.cleanliness.current/pet.cleanliness.max)*100}%;"></div></div>` : ''}
                        ${pet.happiness ? `<div class="progress-bar" style="margin: 5px 0;"><div class="progress-bar-text">快乐度: ${pet.happiness.current}/${pet.happiness.max}</div><div class="progress-bar-inner affection-bar" style="width: ${(pet.happiness.current/pet.happiness.max)*100}%;"></div></div>` : ''}
                    </div>
                    <div class="list-item-action">
                        <button class="styled-button" onclick="
                            logAction('照顾宠物', {petName: '${pet.name}', petId: '${pet.id}'});
