                            })
                        ">照顾</button>
                    </div>
                </div>`).join('');

            const activitiesHTML = gameData.pets.activities.map(activity => `
                <button class="styled-button secondary" onclick="
                    logAction('宠物活动', {activityName: '${activity.name}', activityId: '${activity.id}'});
                    showModal({
                        title: '${activity.name}',
                        content: '${activity.description}<br><br><strong>效果：</strong>${activity.effect}<br><strong>所需时间：</strong>${activity.time}',
                        buttons: [{text: '开始', class: 'primary'}, {text: '取消', class: 'secondary'}]
                    })
                " style="margin: 5px;">${activity.name}</button>`).join('');

            page.innerHTML = `
                <h2>🐕 宠物照顾 🐕</h2>
                <div class="page-container">
                    <p>${parseText(gameData.pets.description)}</p>
                    <div class="item-list">${petsHTML}</div>
                    <div style="margin-top: 20px; text-align: center;">
                        <h4>照顾活动</h4>
                        ${activitiesHTML}
                    </div>
