        }

        function renderTalentPage() {
            const page = document.getElementById('page-talent');

            if (!gameData.talents) {
                page.innerHTML = `
                    <h2>🎭 才艺展示 🎭</h2>
                    <div class="page-container">
                        <p>暂无才艺数据</p>
                    </div>`;
