                </div>`).join('');

            page.innerHTML = `
                <h2>🎭 才艺展示 🎭</h2>
                <div class="page-container">
                    <p>${parseText(gameData.talents.description)}</p>
                    <div class="item-list">${talentsHTML}</div>
                </div>`;
        }

        const displayChoices = (choices) => {
            const container = document.getElementById('player-choices-container');
            const inner = container.querySelector('.choices-inner');

            inner.innerHTML = choices && choices.length > 0 ?
                `<div class="choices-content">
                    ${choices.map(c =>
                        `<button class="choice-button" onclick="handleChoiceClick('${c.text.replace(/'/g, "\\'").replace(/"/g, '&quot;')}');">
                            ${parseText(c.text)}
                        </button>`
                    ).join('')}
                </div>` : '';

            document.getElementById('player-choices-wrapper').style.display =
                choices && choices.length > 0 ? 'block' : 'none';
        };

        function createRosePetals() {
            const container = document.getElementById('rose-petals');
            setInterval(() => {
                if (Math.random() > 0.8) {
                    const petal = document.createElement('div');
                    petal.className = 'petal';
                    petal.style.left = Math.random() * 100 + '%';
                    petal.style.animationDuration = (6 + Math.random() * 4) + 's';
                    petal.style.animationDelay = Math.random() * 2 + 's';
                    container.appendChild(petal);

                    setTimeout(() => {
                        if (container.contains(petal)) {
                            container.removeChild(petal);
                        }
                    }, 10000);
                }
            }, 1500);
        }

        function init() {
            const xmlSrc = document.getElementById('xml-data-source').value;
            if (!xmlSrc) {
                return document.getElementById('game-container').innerHTML =
                    `<div class="error-container"><h3>错误：无XML数据源</h3></div>`;
            }

            try {
                const parser = new DOMParser();
                const xmlDoc = parser.parseFromString(xmlSrc, "application/xml");
                if (xmlDoc.getElementsByTagName("parsererror").length > 0) {
                    throw new Error("XML解析失败");
                }
                gameData = parseXmlData(xmlDoc);
            } catch (e) {
                handleError(e, 'init');
                return document.getElementById('game-container').innerHTML =
                    `<div class="error-container"><h3>初始化失败</h3><p>${e.message}</p></div>`;
            }

            gameState = {
                money: gameData.shop?.funds || 0,
                warehouse: gameData.warehouse?.items ? JSON.parse(JSON.stringify(gameData.warehouse.items)) : [],
                calendar: gameData.calendar ? JSON.parse(JSON.stringify(gameData.calendar)) : {},
                diary: gameData.diary ? JSON.parse(JSON.stringify(gameData.diary)) : {}
            };

            document.title = gameData.config.title;
            if (document.querySelector('.choices-header span:first-child')) {
                document.querySelector('.choices-header span:first-child').textContent =
                    gameData.config.choiceHeader;
            }

            const setupNavBars = () => {
                const navContainer = document.querySelector('.shortcut-bar');
                const groups = { left: [], center: [], right: [] };
                navContainer.innerHTML = '';

                (gameData.nav || []).forEach(group => {
                    const positionKey = group.position === '左' ? 'left' :
                                       group.position === '右' ? 'right' : 'center';
                    groups[positionKey].push(...group.buttons);
                });

                ['left', 'center', 'right'].forEach(pos => {
                    if (groups[pos].length === 0 && pos === 'center' &&
                        (groups.left.length > 0 || groups.right.length > 0)) {
                        const emptyCenterGroupEl = document.createElement('div');
                        emptyCenterGroupEl.className = 'nav-icons-group';
                        emptyCenterGroupEl.style.flexGrow = "1";
                        navContainer.appendChild(emptyCenterGroupEl);
                        return;
                    }

                    if (groups[pos].length > 0) {
                        const groupEl = document.createElement('div');
                        groupEl.className = 'nav-icons-group';

                        if (pos === 'center') {
                            groupEl.style.flexGrow = "1";
                            groupEl.style.justifyContent = "center";
                        } else if (pos === 'right') {
                            groupEl.style.justifyContent = "flex-end";
                        }

                        groups[pos].forEach(btn => {
                            const btnEl = document.createElement('button');
                            btnEl.className = 'nav-button';
                            btnEl.dataset.page = btn.id;
                            btnEl.title = btn.title;
                            btnEl.innerHTML = btn.iconHTML;
                            btnEl.onclick = () => showPage(btn.id);
                            groupEl.appendChild(btnEl);
                        });
                        navContainer.appendChild(groupEl);
                    }
                });
            };

            setupNavBars();

            const choicesHeader = document.querySelector('.choices-header');
            if (choicesHeader) {
                choicesHeader.onclick = (e) => {
                    const container = document.getElementById('player-choices-container');
                    const icon = e.currentTarget.querySelector('.toggle-icon');
                    container.classList.toggle('expanded');
                    icon.style.transform = container.classList.contains('expanded') ?
                        'rotate(180deg)' : 'rotate(0deg)';
                };
            }

            createRosePetals();
            showPage('home');
            displayChoices(gameData.initialScene.choices);
        }

        document.addEventListener("DOMContentLoaded", init);
    })();
    </script>
</body>
</html>
