            overflow-y: auto;
            position: relative;
            z-index: 1;
        }

        .system-log-card .content::-webkit-scrollbar {
            width: 8px;
        }

        .system-log-card .content::-webkit-scrollbar-track {
            background: rgba(0, 0, 0, 0.3);
            border-radius: 4px;
        }

        .system-log-card .content::-webkit-scrollbar-thumb {
            background: var(--gradient-gold);
            border-radius: 4px;
            border: 1px solid rgba(255, 215, 0, 0.3);
        }

        .system-log-card .content::-webkit-scrollbar-thumb:hover {
            background: var(--momoka-gold);
            box-shadow: 0 0 5px var(--shadow-gold);
        }

        /* 日志条目样式 */
        .log-entry {
            margin-bottom: 8px;
            padding: 8px;
            border-radius: 6px;
            background: rgba(255, 255, 255, 0.05);
            border-left: 3px solid var(--momoka-pink);
            transition: all 0.3s ease;
            position: relative;
        }

        .log-entry:last-child {
            margin-bottom: 0;
        }

        .log-entry:hover {
            background: rgba(255, 182, 193, 0.1);
            border-left-color: var(--momoka-deep-pink);
            transform: translateX(3px);
        }

        .log-entry::before {
            content: '📝';
            position: absolute;
            left: -15px;
            top: 8px;
            font-size: 0.8em;
            background: var(--momoka-purple);
            border-radius: 50%;
            width: 20px; height: 20px;
            display: flex;
            align-items: center;
            justify-content: center;
            border: 2px solid var(--momoka-pink);
        }

        .log-timestamp {
            color: var(--momoka-lavender);
            margin-right: 10px;
            font-size: 0.85em;
            opacity: 0.8;
        }

        .log-type {
            color: var(--momoka-gold);
            font-weight: bold;
            text-shadow: 0 1px 2px rgba(255, 215, 0, 0.3);
        }

        .log-details {
            color: #f0e6f5;
            margin-left: 8px;
        }

        .log-details strong {
            color: var(--momoka-pink);
            font-weight: bold;
            text-shadow: 0 1px 2px rgba(255, 182, 193, 0.3);
        }

        /* 特殊操作类型样式 */
        .log-entry[data-type="购买道具"] {
            border-left-color: var(--momoka-gold);
        }

        .log-entry[data-type="购买道具"]::before {
            content: '💰';
        }

        .log-entry[data-type="使用道具"] {
            border-left-color: var(--momoka-deep-pink);
        }

        .log-entry[data-type="使用道具"]::before {
            content: '🎯';
        }

        .log-entry[data-type="查看详情"] {
            border-left-color: var(--momoka-lavender);
        }

        .log-entry[data-type="查看详情"]::before {
            content: '👁️';
        }

        .log-entry[data-type="花园活动"],
        .log-entry[data-type="宠物活动"],
        .log-entry[data-type="茶会活动"] {
            border-left-color: #90EE90;
        }

        .log-entry[data-type="花园活动"]::before {
            content: '🌹';
        }

        .log-entry[data-type="宠物活动"]::before {
            content: '🐕';
        }

        .log-entry[data-type="茶会活动"]::before {
            content: '☕';
        }

        /* 响应式适配 */
        @media (max-width: 768px) {
            .styler-wrapper {
                max-width: 96%;
            }

            .user-input-card .header,
            .system-log-card .header {
                padding: 10px 12px;
                font-size: 0.9em;
            }

            .user-input-card .content,
            .system-log-card .content {
                padding: 12px;
                font-size: 0.95em;
            }

            .system-log-card .content {
                max-height: 200px;
                font-size: 0.85em;
            }

            .log-entry {
                padding: 6px;
                margin-bottom: 6px;
            }

            .log-timestamp {
                font-size: 0.8em;
            }
        }

        /* 动画效果 */
        .styler-wrapper {
            animation: fadeInUp 0.5s ease-out;
        }

        @keyframes fadeInUp {
            from {
                opacity: 0;
                transform: translateY(20px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        /* 特殊文本装饰 */
        .user-input-card .content em {
            color: var(--momoka-deep-pink);
            font-style: italic;
            background: linear-gradient(45deg, var(--momoka-lavender), transparent);
            padding: 0 3px;
            border-radius: 3px;
        }

        .user-input-card .content strong {
            color: var(--momoka-purple);
            font-weight: bold;
            text-shadow: 0 1px 2px rgba(139, 0, 139, 0.3);
        }

        /* 桃华特色语气词装饰 */
        .content:has-text("ですわ"),
        .content:has-text("deswa") {
            position: relative;
        }

        .content:has-text("ですわ")::after,
        .content:has-text("deswa")::after {
            content: '✨';
            position: absolute;
            bottom: 8px;
            right: 8px;
            font-size: 1.2em;
            opacity: 0.6;
            animation: sparkle 3s infinite;
        }
    </style>
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css">
</head>
<body>
    <div id="styler-container"></div>
    <script>
        (function() {
            const rawInput = `$1`;
            const container = document.getElementById('styler-container');

            // 识别系统日志的条件
            const isSystemLog = rawInput.includes('<用户操作记录>') ||
                               rawInput.trim().startsWith('【USER】 [选择]');

            if (isSystemLog) {
                // 渲染系统日志
                const choiceMatch = rawInput.match(/\[选择\]\s*([\s\S]*?)(?=<用户操作记录>|\n\n|$)/);
                const choiceText = choiceMatch ? choiceMatch[1].trim() : '执行桃华的指示';

                let logContentHTML = '';
                const logXmlMatch = rawInput.match(/<用户操作记录>([\s\S]*?)<\/用户操作记录>/);

                if (logXmlMatch) {
                    try {
                        const parser = new DOMParser();
                        const xmlDoc = parser.parseFromString(`<root>${logXmlMatch[1]}</root>`, "application/xml");
                        const operations = xmlDoc.querySelectorAll('操作');

                        if (operations.length === 0 && logXmlMatch[1].trim() !== '') {
                            logContentHTML = `解析遇到困难，原始记录：<br><pre style="font-size:0.8em;opacity:0.7;">${logXmlMatch[1].replace(/</g, "&lt;").replace(/>/g, "&gt;")}</pre>`;
                        } else if (operations.length === 0) {
                            logContentHTML = '<div class="log-entry">本次互动暂无详细操作记录</div>';
                        }

                        operations.forEach(op => {
                            const type = op.getAttribute('类型') || '未知操作';
                            const timestampAttr = op.getAttribute('时间');
                            const timestamp = timestampAttr ?
                                new Date(timestampAttr).toLocaleTimeString('zh-CN', {
                                    hour: '2-digit',
                                    minute: '2-digit',
                                    second: '2-digit',
                                    hour12: false
                                }) : '??:??:??';
                            const cdata = op.textContent.trim();
                            let details = '';

                            try {
                                const jsonData = JSON.parse(cdata);
                                switch(type) {
                                    case '购买道具':
                                        details = `道具: <strong>${jsonData.itemName || jsonData.name}</strong> ${jsonData.itemId ? `(ID: ${jsonData.itemId})` : ''}, 花费: ${jsonData.price || '未知'}`;
                                        break;
                                    case '使用道具':
                                        details = `使用道具: <strong>${jsonData.itemName}</strong> ${jsonData.itemId ? `(ID: ${jsonData.itemId})` : ''}`;
                                        break;
                                    case '查看道具详情':
                                    case '查看玫瑰详情':
                                    case '查看课程详情':
                                    case '查看日志详情':
                                    case '查看日历计划':
                                        details = `查看详情: <strong>${jsonData.itemName || jsonData.roseName || jsonData.courseName || jsonData.entryId || '未知'}</strong>`;
                                        break;
                                    case '花园活动':
                                        details = `花园活动: <strong>${jsonData.activityName}</strong>`;
                                        break;
                                    case '宠物活动':
                                        details = `宠物活动: <strong>${jsonData.activityName}</strong>`;
                                        break;
                                    case '照顾宠物':
                                        details = `照顾宠物: <strong>${jsonData.petName}</strong>`;
                                        break;
                                    case '观看才艺':
                                        details = `观看才艺: <strong>${jsonData.talentName}</strong>`;
                                        break;
                                    case '选择茶饮':
                                        details = `选择茶饮: <strong>${jsonData.teaName}</strong>`;
                                        break;
                                    case '选择点心':
                                        details = `选择点心: <strong>${jsonData.dessertName}</strong>`;
                                        break;
                                    case '系统错误':
                                        details = `错误上下文: <strong>${jsonData.context}</strong>, 错误信息: ${jsonData.error}`;
                                        break;
                                    default:
                                        details = Object.entries(jsonData)
                                            .map(([key, value]) => `${key}: ${typeof value === 'object' ? JSON.stringify(value) : value}`)
                                            .join(', ');
                                        break;
                                }
                            } catch (e) {
                                details = cdata || '无详细信息';
                            }

                            logContentHTML += `<div class="log-entry" data-type="${type}">
                                <span class="log-timestamp">[${timestamp}]</span>
                                <span class="log-type">${type}:</span>
                                <span class="log-details">${details}</span>
                            </div>`;
                        });
                    } catch (e) {
                        console.error("解析操作记录XML时出错:", e);
                        logContentHTML = '<div class="log-entry">操作记录解析失败</div>';
                    }
                } else if (choiceText !== '执行桃华的指示' && choiceText !== '') {
                    logContentHTML = '<div class="log-entry">本次选择无附加操作日志</div>';
                }

                container.innerHTML = `
                    <div class="styler-wrapper system-log-card">
                        <div class="header">
                            <i class="fas fa-crown"></i>
                            桃华的管教记录: ${choiceText}
                        </div>
                        <div class="content">${logContentHTML || '<div class="log-entry">暂无操作记录</div>'}</div>
                    </div>
                `;

            } else {
                // 渲染用户输入
                let processedInput = rawInput
                    .replace(/</g, "&lt;")
                    .replace(/>/g, "&gt;")
                    .replace(/\n/g, "<br>");

                // 特殊格式处理
                processedInput = processedInput
                    .replace(/\*\*(.*?)\*\*/g, (match, group1) => `<span style="background: var(--gradient-gold); color: var(--momoka-purple); padding: 2px 6px; border-radius: 8px; font-weight: bold;">${group1}</span>`)
                    .replace(/\*(.*?)\*/g, (match, group1) => `<strong>${group1}</strong>`)
                    .replace(/_(.*?)_/g, (match, group1) => `<em>${group1}</em>`)
                    .replace(/(ですわ|deswa)/g, (match, group1) => `<span style="color: var(--momoka-deep-pink); font-weight: bold; position: relative;">${group1}<span style="position: absolute; top: -2px; right: -15px; font-size: 0.8em; opacity: 0.7;">✨</span></span>`);

                container.innerHTML = `
                    <div class="styler-wrapper user-input-card">
                        <div class="header">
                            <i class="fas fa-heart"></i>
                            您向桃华妈妈的倾诉
                        </div>
                        <div class="content">${processedInput}</div>
                    </div>
                `;
            }
        })();
    </script>
</body>
</html>
```

